<?php require __DIR__.'/../config.php';require __DIR__.'/../functions.php';requireAdmin();$rows=db()->query('SELECT f.*,u.name customer_name,b.booking_code,c.name car_name FROM feedback f LEFT JOIN users u ON u.id=f.customer_id LEFT JOIN bookings b ON b.id=f.booking_id LEFT JOIN cars c ON c.id=b.car_id ORDER BY f.created_at DESC')->fetchAll();adminTop('Customer Feedback','feedback');?><div class="table-wrap"><table><thead><tr><th>Date</th><th>Customer</th><th>Booking</th><th>Vehicle</th><th>Rating</th><th>Feedback</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['customer_name']??'Guest')?></td><td><?=e($r['booking_code']??'-')?></td><td><?=e($r['car_name']??'-')?></td><td><?=e($r['rating']??'-')?>/5</td><td><?=e($r['feedback_text']??'')?></td></tr><?php endforeach;?></tbody></table></div><?php adminBottom(); ?>